package com.abhiai.abhiai_backend.service;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.abhiai.abhiai_backend.dto.recommendation.SignalRequest;import com.abhiai.abhiai_backend.entity.RecommendationSignal;import com.abhiai.abhiai_backend.exception.UserNotFoundException;import com.abhiai.abhiai_backend.repository.*;@Service public class RecommendationSignalService{private final RecommendationSignalRepository signals;private final UserRepository users;public RecommendationSignalService(RecommendationSignalRepository s,UserRepository u){signals=s;users=u;}@Transactional public void record(UUID id,SignalRequest r){var u=users.findById(id).orElseThrow(UserNotFoundException::new);signals.save(new RecommendationSignal(u,r.type(),r.entityType().toUpperCase(),r.entityId()));}}
